57	// Shallow-merges top-level keys from source into target.
58	// Object values (e.g. "rules") are merged one level deep with source taking precedence.
59	// Scalar values are overwritten by source.
60	function mergeInto(target: Ruleset, source: Ruleset): void {
61	  for (const key of Object.keys(source)) {
62	    const sourceVal = source[key];
63	    const targetVal = target[key];
64	    target[key] = isPlainObject(targetVal) && isPlainObject(sourceVal) ? { ...targetVal, ...sourceVal } : sourceVal;
65	  }
66	}
