99	// Fetches and parses a remote ruleset over the network. The URL is SSRF-checked before
100	// any network call is made. Redirects are rejected because a redirect could forward us
101	// to an internal host that bypassed the assertSafeRemoteUrl check.
102	async function readRemoteRuleset(url: URL): Promise<Ruleset> {
103	  await assertSafeRemoteUrl(url);
104	
105	  let response: Response;
106	  try {
107	    response = await fetch(url, { redirect: 'error', signal: AbortSignal.timeout(REMOTE_FETCH_TIMEOUT_MS) });
108	  } catch (error) {
109	    const reason = error instanceof Error ? error.message : String(error);
110	    throw new Error(`Failed to fetch remote "extends" ruleset "${url.href}": ${reason}`);
111	  }
112	  if (!response.ok) {
113	    throw new Error(
114	      `Failed to fetch remote "extends" ruleset "${url.href}": ${response.status} ${response.statusText}`,
115	    );
116	  }
117	
118	  const parsed = YAML.parse(await response.text());
119	  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
120	    throw new Error(`Remote "extends" ruleset "${url.href}" must be an object at the top level.`);
121	  }
122	  return parsed as Ruleset;
