132	  if (depth > MAX_EXTENDS_DEPTH) {
133	    throw new Error(`"extends" nested too deeply (max ${MAX_EXTENDS_DEPTH}) at ${url.href}`);
134	  }
135	  if (visited.has(url.href)) {
136	    throw new Error(`"extends" cycle detected at ${url.href}`);
137	  }
138	
139	  const ruleset = await readRemoteRuleset(url);
140	  const validation = validateSpectralRuleset(YAML.stringify(ruleset));
141	  if (!validation.isValid) {
142	    throw new Error(`Remote ruleset at "${url.href}" failed validation: ${validation.error}`);
143	  }
144	
145	  const nextVisited = new Set(visited).add(url.href);
146	  for (const entry of toArray(ruleset.extends)) {
147	    if (Array.isArray(entry)) {
148	      throw new TypeError(
149	        `Failed to process "extends" entry ${JSON.stringify(entry)}: tuple format (e.g. [path, severity]) is not supported. Use a plain string instead.`,
