import fs from 'node:fs';
import path from 'node:path';

import electron from 'electron';

import { compileSpectralRulesetFromContent } from '~/common/bundle-spectral-ruleset';

// ** For main process only. Do not import this file into the renderer **
// Persists a project's compiled Spectral ruleset to disk so the lint worker can read a
// self-contained file with no remote references. Recompilation is skipped when the source content
// is unchanged and the compiled file is still present, keyed by a content hash held in memory.

// projectId -> sha256 of the last content successfully compiled and written for that project.
const contentHashByProject = new Map<string, string>();

function dataPath(): string {
  return process.env.INSOMNIA_DATA_PATH || electron.app.getPath('userData');
}

function hashContent(content: string): string {
  return crypto.createHash('sha256').update(content).digest('hex');
}

// Absolute path where the compiled ruleset for a project is stored.
export function compiledRulesetPathFor(projectId: string): string {
  return path.join(dataPath(), 'projects', projectId, '.spectral.yaml');
}

// Compiles the given YAML content and writes it to the project's compiled ruleset path.
// Uses a content-hash cache: if the content is unchanged and the compiled file still exists on
// disk, recompilation and the file write are skipped. If the file was deleted externally the
// content is recompiled and rewritten. Errors from compilation are propagated to the caller.
export async function writeCompiledRuleset(projectId: string, content: string): Promise<{ compiledPath: string }> {
  const compiledPath = compiledRulesetPathFor(projectId);
  const hash = hashContent(content);

  if (contentHashByProject.get(projectId) === hash) {
    try {
      await fs.promises.access(compiledPath);
      // Unchanged content and the compiled file is still present — nothing to do.
      return { compiledPath };
    } catch {
      // File was removed externally (e.g. ENOENT); fall through to recompile and rewrite.
    }
  }

  const compiled = await compileSpectralRulesetFromContent(content);
  await fs.promises.mkdir(path.dirname(compiledPath), { recursive: true });
  await fs.promises.writeFile(compiledPath, compiled, { encoding: 'utf8' });
  contentHashByProject.set(projectId, hash);
  return { compiledPath };
}

// Removes the project's compiled ruleset directory and clears its in-memory content-hash entry so
// the next writeCompiledRuleset call always recompiles.
export async function deleteCompiledRuleset(projectId: string): Promise<void> {
  await fs.promises.rm(path.dirname(compiledRulesetPathFor(projectId)), { recursive: true, force: true });
  contentHashByProject.delete(projectId);
}
